def family_init(ctx):
    ctx.e = ctx.indicator("ema", period=int(ctx.p.ema_n))
    b = ctx.bars
    n = len(b)
    closes = [float(x["c"]) for x in b]
    highs = [float(x["h"]) for x in b]
    k = [0] * n
    run = 0
    for j in range(1, n):
        run = run + 1 if closes[j] > highs[j - 1] else 0
        k[j] = run
    ctx.k = ctx.series(k, "streak_count")


def signal(ctx, i):
    if i < 1:
        return 0
    k = ctx.k[i]
    pk = ctx.k[i - 1]
    if k is None or pk is None:
        return 0
    thr = int(ctx.p.streak)
    if k < thr or pk >= thr:
        return 0
    if int(ctx.p.ema_on):
        e = ctx.e[i]
        if e is None or ctx.c[i] >= e:
            return 0
    return -1


def exit_signal(ctx, i):
    if i < 1:
        return False
    return ctx.c[i] < ctx.l[i - 1]
